"use client";
import type { CSSProperties } from "react";
import { ButtonSurface, buttonVariables, type AnimationButtonProps } from "./button-shared";
export interface CircleFillButtonProps extends AnimationButtonProps {
  delay?: number;
}
const css = `
.z-anb-circle{overflow:hidden}.z-anb-circle-fill{position:absolute;z-index:0;left:var(--z-anb-x,50%);top:var(--z-anb-y,50%);width:var(--z-anb-diameter,220%);height:var(--z-anb-diameter,220%);border-radius:50%;background:var(--z-anb-fill);pointer-events:none;transform:translate(-50%,-50%) scale(0);transition:transform var(--z-anb-duration) var(--z-anb-easing)}
.z-anb-circle[data-active=true] .z-anb-circle-fill{transform:translate(-50%,-50%) scale(1);transition-delay:var(--z-anb-delay,0s)}
`;
/** The pointer entry point is the center of a circle sized to the farthest corner. */
export function CircleFillButton({
  children = "Explore Performance Collection",
  duration = 0.8,
  easing = "cubic-bezier(.16,1,.3,1)",
  delay = 0,
  ...props
}: CircleFillButtonProps) {
  return (
    <>
      <style>{css}</style>
      <ButtonSurface
        {...props}
        duration={duration}
        easing={easing}
        variant="circle"
        variables={
          {
            ...buttonVariables({ ...props, duration, easing }),
            "--z-anb-delay": `${Math.max(0, delay)}s`,
          } as CSSProperties
        }
        onEngage={(element, event) => {
          const box = element.getBoundingClientRect();
          const x = event
            ? Math.max(0, Math.min(box.width, event.clientX - box.left))
            : box.width / 2;
          const y = event
            ? Math.max(0, Math.min(box.height, event.clientY - box.top))
            : box.height / 2;
          const radius = Math.hypot(Math.max(x, box.width - x), Math.max(y, box.height - y));
          element.style.setProperty("--z-anb-x", `${x}px`);
          element.style.setProperty("--z-anb-y", `${y}px`);
          element.style.setProperty("--z-anb-diameter", `${radius * 2 + 2}px`);
        }}
      >
        <span className="z-anb-circle-fill" aria-hidden="true" />
        <span className="z-anb-label">{children}</span>
      </ButtonSurface>
    </>
  );
}
